#!/usr/bin/env python3
"""Summarize per-LP saved/deaths output generated by `egress --escape-stats <FILE>`."""

import argparse
from pathlib import Path


def summarize_escape_stats(path: Path) -> None:
    saved = {}
    deaths = {}
    with path.open("r", encoding="utf-8") as f:
        for raw_line in f:
            line = raw_line.strip()
            if not line:
                continue
            if line.startswith("-"):
                print(f"saved {sum(saved.values())}, deaths {sum(deaths.values())}")
                continue
            parts = line.split()
            if len(parts) == 3:
                lp_id, s, d = (int(tok) for tok in parts)
                saved[lp_id] = s
                deaths[lp_id] = d
            elif len(parts) == 2:
                s, d = (int(tok) for tok in parts)
                print(f"saved {s}, deaths {d}")
                return

    print(f"saved {sum(saved.values())}, deaths {sum(deaths.values())}")


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Summarize per-LP saved and death counts from an egress --escape-stats file."
    )
    parser.add_argument(
        "stats_file",
        nargs="?",
        type=Path,
        default=Path("escape_stats.txt"),
        help="Path to the per-LP stats file (default: escape_stats.txt)",
    )
    args = parser.parse_args()
    summarize_escape_stats(args.stats_file)


if __name__ == "__main__":
    main()
